import { GEO } from './bielany-geodata.js';

// js/city-config.js
// Bielany (Warsaw) spatial configuration & street database at true 1:1 scale, derived from js/bielany-geodata.js
// (generated by tools/geo-bielany.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), origin at the Stare Bielany metro station, no rotation.
// The MVP area runs from Młociny (north-west) to Stare Bielany (south-east), ~3.1 km x 2.9 km. The ground is flat.
//
// The portable modules (controllers, cameras, audio, traffic) read the city through the names exported here; the
// New York ones that have no Bielany counterpart (Central Park, the shore, numbered streets) stay as neutral stand-ins.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};

// ---------------------------------------------------------------------------------------------------------------------
// The MVP area: its bounds stand in for the island (a flat plate, no shore); curbs 15 cm high
// ---------------------------------------------------------------------------------------------------------------------
const AREA = GEO.frame.bounds;
const ISLAND_BOUNDS = { minX: AREA.minX, maxX: AREA.maxX, minZ: AREA.minZ, maxZ: AREA.maxZ, sidewalkHeight: 0.15, waterLevel: -2.2 };
/** West & east edge of the area at any z (the MVP area is a rectangle) */
function getIslandBoundsAtZ() {
  return { westX: AREA.minX, eastX: AREA.maxX };
}
// No Central Park and no harbour in Bielany: an empty box far away, and no shorelines
const CENTRAL_PARK_BOUNDS = { minX: 1e6, maxX: 1e6, minZ: 1e6, maxZ: 1e6 };
const NJ_SHORELINE_POLYGON = [];
const LONG_ISLAND_POLYGONS = [];
// No numbered streets either (kept for the portable modules' imports)
const streetZ = () => 0;

// ---------------------------------------------------------------------------------------------------------------------
// Named roads (OpenStreetMap ways merged per street) — maps, labels & lookups
//   cls: trunk, primary, secondary, tertiary, local, living (strefa zamieszkania), service, pedestrian
// ---------------------------------------------------------------------------------------------------------------------
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat, cls]) => ({ name, raw: name, w, dir, lanes, highway: !!hw, cls, pts: toPts(flat) }));

// Nearest-road index (labels, teleports): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const key = s.r.name || s.r;
      const prev = best.get(key);
      if (!prev || d < prev.dist) best.set(key, { road: s.r, dist: d });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: the curb islands between the roadways (tools/geo-bielany.mjs, from a 1 m raster of the streets at their
// widths), raised to the curb height, with their sidewalks along the curbs
//   poly: curb outline [{x, z}], holes: roadway islands inside it, park / median: kept for the portable modules (none)
// ---------------------------------------------------------------------------------------------------------------------
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
const bounded = (o) => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of o.poly) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return Object.assign(o, { minX, maxX, minZ, maxZ });
};
const BLOCKS = GEO.blocks.map(([outer, holes, area], id) =>
  bounded({ id, poly: toPts(outer), holes: holes.map(toPts), area, park: 0, parkName: '', median: false }));
const SIDEWALKS = GEO.sidewalks.map(([block, outer, holes]) => bounded({ block: BLOCKS[block], poly: toPts(outer), holes: holes.map(toPts) }));
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
/** The block (curb island) under (x, z), or null on the roadway */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (pointInPoly(b.poly, x, z) && !b.holes.some((h) => pointInPoly(h, x, z))) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// Buildings' footprints (js/bielany-geodata.js, buildings.js), indexed for point tests: sidewalks & crosswalks keep
// out of them
const BUILDINGS = GEO.buildings.map(([outer, holes, h], id) => bounded({ id, poly: toPts(outer), holes: holes.map(toPts), h }));
const BUILDING_GRID = new Map();
for (const b of BUILDINGS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BUILDING_GRID.has(k)) BUILDING_GRID.set(k, []);
      BUILDING_GRID.get(k).push(b);
    }
  }
}
/** The building standing at (x, z), or null */
function buildingAt(x, z) {
  for (const b of BUILDING_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL)) || []) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (pointInPoly(b.poly, x, z) && !b.holes.some((h) => pointInPoly(h, x, z))) return b;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Places: the M1 stations (more in step 1.8a) and the teleport arrivals, on real roadways
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARKS = [
  ...GEO.stations.map((s) => ({ id: s.name, name: `Metro ${s.name}`, short: s.name, x: s.x, z: s.z, district: 'Bielany' })),
  { id: 'AWF', name: 'Akademia Wychowania Fizycznego', short: 'AWF', x: 330, z: -760, district: 'Las Bielański' },
  { id: 'Hutnik', name: 'Stadion Hutnika', short: 'Hutnik', x: -374.5, z: -2020.8, district: 'Bielany' }
];
// Street-level arrivals shared by every travel mode, in the direction of travel. Heading 0 faces south (+z), PI north.
const TELEPORT_LOCATIONS = {
  stareBielany: { x: 9.4, z: -12.4, heading: -2.216 }, // Kasprowicza at the Stare Bielany station
  wawrzyszew: { x: -659.3, z: -518.8, heading: -2.215 }, // Kasprowicza at the Wawrzyszew station
  mlociny: { x: -1336.5, z: -1005.0, heading: -0.413 }, // al. gen. Marii Wittek at the Młociny station
  awf: { x: 205.9, z: -638.1, heading: -2.583 }, // Marymoncka at the AWF
  chomiczowka: { x: -1645.6, z: 502.2, heading: -0.584 }, // Pabla Nerudy, Chomiczówka
  wrzeciono: { x: -690.4, z: -1224.9, heading: 2.115 }, // Przy Agorze, Wrzeciono
  slodowiec: { x: 710.9, z: 543.0, heading: 2.634 }, // rondo AWF at the Słodowiec station
  marymont: { x: 1548.7, z: 1121.3, heading: 1.218 }, // Słowackiego at the Marymont station
  piaski: { x: -319.5, z: 1452.3, heading: 1.185 }, // Kochanowskiego, Piaski
  kaskada: { x: 1196.4, z: 284.8, heading: 0.769 }, // Gdańska, Marymont-Kaskada
  kameduly: { x: 597.1, z: -1583.6, heading: -0.503 }, // Dewajtis by the Camaldolese church
  hutnik: { x: -555.9, z: -1953.8, heading: 0.545 }, // Marymoncka, a short walk from Stadion Hutnika
  mostPolnocny: { x: -95.0, z: -2570.0, heading: 2.25 } // the west end of the Skłodowska-Curie bridge, towards the Vistula
};

/**
 * Street or place name at any world (x, z): "Metro X · Street & Cross Street" near a station, "Street & Cross Street"
 * (the two nearest named roads within ~25 m beyond their curbs), one street, or "Bielany"
 */
function getLocationLabel(x, z) {
  const near = nearestRoads(x, z, 60).filter((r) => r.road.name && r.dist - r.road.w * 0.5 < 25).map((r) => r.road.name);
  const streets = near.slice(0, 2).join(' & ');
  for (const lm of LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) return streets ? `${lm.name} · ${streets}` : lm.name;
  }
  return streets || 'Bielany';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads and the traffic (traffic.js), in seconds: the main road (right-of-way
// group 0) green until avenueAmber, amber until avenueRed; the crossing roads green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off only
// on the WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the slowest
// walker to get across the widest road.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// Version for the district office: the address carries ?urzad (decision of 2026-10-26). Read from the URL so one build
// serves both versions; outside a browser (tests, Node) there is no location and the game runs as usual.
const urzadMode = (search) => new URLSearchParams(search).has('urzad');
const URZAD = urzadMode(typeof location !== 'undefined' ? location.search : '');
if (URZAD && typeof document !== 'undefined') document.body.classList.add('urzad'); // shows the label (style.css)

// Pedestrians are solid: the player bumps into them, and a car or bike hitting one fast enough knocks them down
// (ragdoll, js/pedestrians.js). Off in the district office's version (URZAD): one switch.
const PEDESTRIAN_CONTACT = !URZAD;

// 'green', 'amber' or 'red' for main-road (isAvenue) or crossing-road traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside main-road (or crossing-road) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

export {
  URZAD,
  urzadMode,
  PEDESTRIAN_CONTACT,
  ISLAND_BOUNDS,
  CENTRAL_PARK_BOUNDS,
  NJ_SHORELINE_POLYGON,
  LONG_ISLAND_POLYGONS,
  ROADS,
  LANDMARKS,
  TELEPORT_LOCATIONS,
  BLOCKS,
  SIDEWALKS,
  BUILDINGS,
  SIGNAL_TIMING,
  getIslandBoundsAtZ,
  streetZ,
  blockAt,
  blocksInRect,
  buildingAt,
  nearestRoads,
  getLocationLabel,
  isTypingInField,
  signalPhase,
  walkSignal
};
